lib_enum_constant	all-enum-constants
lib_expression	all-expressions
lib_field	all-fields
lib_field_position	all-field-positions
lib_import	all-imports
lib_local_variable	all-local-variables
lib_method	all-methods
lib_method_parameter	all-method-parameters
lib_method_type_parameter	all-method-type-parameters
lib_type	all-types
lib_type_lines	all-types
lib_type_parameter	all-type-parameters
lib_type_reference	all-type-references
lib_service_descriptor	all-service-descriptors
lib_service_provider	all-service-providers
